def field(name,label,value='',kind='number',hint='',options=None):
 control='<select name="'+name+'">'+''.join(f'<option value="{v}">{e(t)}</option>' for v,t in options)+'</select>' if options else '<input name="'+name+'" type="'+kind+'" value="'+e(value)+'"'+(' step="any" required' if kind=='number' else '')+'>'
 return '<label>'+e(label)+control+('<small class="tools-help">'+e(hint)+'</small>' if hint else '')+'</label>'
def calc(slug,title,desc,fields,helptext):
 body='<div class="portal-split"><div><form class="portal-form" data-calculator="'+slug+'">'+''.join(fields)+'<button class="rex-button full" type="submit">Calculate</button></form></div><aside><div class="tool-result" id="tool-result" role="status" aria-live="polite"><h2>Your result</h2><p>Check the illustrative inputs and select Calculate.</p></div><p class="tools-help">Examples are hypothetical. Verify contract specifications, costs and conversion rates with your provider. Planned stop losses are not guaranteed execution prices.</p></aside></div><div class="portal-band"><h2>How this calculation works</h2>'+helptext+'</div><noscript>JavaScript is needed for the calculator. The formula remains available below the inputs.</noscript>'
 page('/tools/'+slug+'/',title,desc,body,['portal-math.js','portal-tools.js'])
calc('position-size','Position size calculator','Translate a cash risk budget and stop distance into lots, rounded down to the allowed lot step.',[
field('equity','Account equity',10000),field('risk','Risk budget (%)',1),field('distance','Entry-to-stop distance (quote price units)',10,hint='Gold example: 3000 to 2990 is 10. EUR/USD: 1.1000 to 1.0980 is 0.0020.'),field('contract','Base units per lot',100,hint='Gold often uses 100 oz; standard FX commonly uses 100,000 base units. Verify your contract.'),field('rate','Account currency per 1 quote currency',1,hint='For a USD account and USD quote, use 1.'),field('step','Allowed lot step',0.01),field('costs','Estimated round-trip costs per lot (account currency)',0)],'<p>Risk budget = equity × risk percentage. Cost per lot = stop distance × contract size × conversion rate + costs per lot. Divide the budget by that cost, then round down to the lot step.</p><p>Illustration: a 100 cash budget and a 10 price-unit stop on a 100-unit contract allow 0.10 lots before costs when both currencies match.</p>')
calc('pip-value','Pip value calculator','Find the cash value of a pip for your contract, size and account currency.',[field('pip','Pip size',0.0001),field('units','Base units per lot',100000),field('lots','Position size (lots)',0.1),field('rate','Account currency per 1 quote currency',1)],'<p>Pip value = pip size × base units per lot × lots × quote-to-account conversion rate.</p><p>At 0.10 lots of 100,000 units and a pip size of 0.0001, one pip is 1 quote-currency unit. Gold pip conventions vary by broker; use its actual specification.</p>')
calc('pivot-points','Pivot point calculator','Calculate reference levels from one completed period. Choose a formula and keep all inputs from the same period.',[field('high','Previous period high',110),field('low','Previous period low',90),field('close','Previous period close',100),field('open','Previous period open (used by DeMark)',100),field('method','Method',options=[('classic','Classic'),('fibonacci','Fibonacci'),('woodie','Woodie — close weighted'),('camarilla','Camarilla'),('demark','DeMark')])],'<p>Classic pivot P = (high + low + close) / 3. R1 = 2P − low; S1 = 2P − high; R2/S2 = P ± range. Other methods use different weights or range multipliers.</p><p>This Woodie variant weights the previous close twice. Verify the convention used by your platform. These are reference levels, not predictions.</p>')
calc('gain-loss','Gain, loss & recovery calculator','Measure the change in equity and the return needed to recover a loss.',[field('start','Starting equity',10000),field('end','Ending equity',8000)],'<p>Return = (ending / starting − 1) × 100%. Recovery from a loss = (starting / ending − 1) × 100%.</p><p>Falling from 10,000 to 8,000 is a 20% loss. Recovering from 8,000 to 10,000 requires 25%. External deposits and withdrawals distort this simple comparison.</p>')
calc('risk-reward','Risk / reward calculator','Compare planned price-distance risk with the distance to your target.',[field('side','Direction',options=[('long','Long / buy'),('short','Short / sell')]),field('entry','Entry price',100),field('stop','Stop price',95),field('target','Target price',110)],'<p>Reward multiple = absolute(target − entry) / absolute(entry − stop). This is a price-distance ratio before costs.</p><p>Entry 100, stop 95 and target 110 gives 2 units of planned reward for 1 unit of planned risk. A high ratio alone says nothing about the probability of reaching the target.</p>')
calc('currency-converter','Currency converter','Convert using published daily reference rates, with an optional fee estimate.',[field('amount','Amount',1000),field('base','From',options=[(x,x) for x in ['USD','EUR','GBP','JPY','AUD','CAD','CHF','NZD','SGD','THB']]),field('quote','To',options=[(x,x) for x in ['EUR','USD','GBP','JPY','AUD','CAD','CHF','NZD','SGD','THB']]),field('fee','Estimated percentage fee (%)',0)],'<p>The conversion is calculated locally using <a href="https://frankfurter.dev/">Frankfurter</a> daily reference rates. The returned date is shown with the result. These are not executable broker quotes.</p><p>Estimate after fee = amount × reference rate × (1 − fee / 100). Fixed fees and other spreads are not included.</p>')
page('/tools/currency-correlation/','Currency correlation','Compare aligned daily returns, or calculate a correlation from your own matching price series.',note('The live-data mode uses daily reference rates, not intraday broker prices. Correlation describes this sample; it is not a forecast.')+'<div data-market="correlation"><div class="data-bar"><p class="market-status" role="status">Loading daily reference data…</p><button class="rex-button secondary" data-refresh>Refresh data</button></div><div class="table-scroll" data-market-output></div></div><div class="portal-band"><h2>Use your own data</h2><p>Paste at least four prices per series, oldest first, separated by commas or whitespace. Each row must represent the same timestamp in both series.</p><form class="portal-form" data-calculator="correlation"><label>Series A<textarea name="a" rows="4" required placeholder="100, 102, 101, 104, 103"></textarea></label><label>Series B<textarea name="b" rows="4" required placeholder="80, 81, 80, 83, 82"></textarea></label><button type="submit" class="rex-button">Calculate correlation</button></form><div id="tool-result" class="tool-result" role="status"><p>Your Pearson correlation of period returns will appear here.</p></div></div>',['portal-math.js','portal-tools.js','portal-markets.js'])
page('/tools/market-hours/','Forex market hours','See conventional trading-session windows in your timezone, with daylight-saving adjustments.', '<label>Display timezone <select id="session-zone">'+''.join(f'<option value="{z}">{label}</option>' for z,label in [('local','Your device timezone'),('UTC','UTC'),('Asia/Ho_Chi_Minh','Vietnam'),('Europe/London','London'),('America/New_York','New York'),('Asia/Tokyo','Tokyo'),('Australia/Sydney','Sydney')])+'</select></label><p id="session-now" class="market-status" role="status"></p><div id="sessions" class="portal-grid"></div>'+note('Windows: Sydney 08:00–17:00, Tokyo 09:00–18:00, London 08:00–17:00 and New York 08:00–17:00 in each city’s local time. The broad FX week is Sunday 17:00 to Friday 17:00 New York time. These are conventional session guides, not exchange or broker opening guarantees; holidays and product breaks are not included.'),['portal-tools.js'])
calc('risk-on-risk-off','Risk appetite worksheet','A manual scenario check across three market observations. Enter changes over the same period.',[field('stocks','Broad equity index change (%)',0),field('vix','Volatility index change (%)',0),field('spreads','Credit spread change (basis points)',0)],'<p>This is a manual breadth score, not a live sentiment feed or the BabyPips meter. Stocks rising, volatility falling and credit spreads narrowing each contribute +1. Opposite moves contribute −1; unchanged contributes 0.</p><p>Score = sum / 3 × 100. Equal weights and directional signs are a deliberately simple worksheet. Divergent signals are common and the score does not recommend a trade.</p>')
